<script setup lang="ts">
import { computed,ref,onMounted } from 'vue'
import { useRoute } from 'vue-router'
import { useLinks,stageLabels,linkErrors } from '../lib/links'
import { dateLabel,secureUrl } from '../lib/format'
import { useApp } from '../stores/app'
import Icon from '../components/Icon.vue'
import LinkAttachments from '../components/LinkAttachments.vue'
const app=useApp(),route=useRoute(),box=useLinks(),tab=ref(route.query.tab==='briefs'?'快讯':'收件箱'),url=ref(''),reason=ref(''),query=ref(''),filter=ref('全部'),error=ref(''),working=ref('')
const rows=computed(()=>box.items.value.filter(i=>(tab.value==='快讯'?i.origin==='collector':i.origin!=='collector')&&(filter.value==='已归档'?i.stage==='archived':i.stage!=='archived')&&(filter.value!=='待处理'||!i.post_id)&&`${i.title} ${i.canonical_url} ${i.tags.join(' ')}`.toLowerCase().includes(query.value.toLowerCase())))
const host=(url:string)=>{try{return new URL(url).hostname}catch{return '原始出处'}}
const last=computed(()=>box.runs.value[0])
async function refresh(){try{await box.load()}catch(e){error.value=app.errorMessage(e)}}
async function submit(){working.value='submit';error.value='';try{const result=await box.action('submit',{items:[{url:url.value,title:'',reason:reason.value,tags:[],category:'科技'}]});url.value='';reason.value='';app.notify(result.items[0]?.duplicate?'链接已在收件箱中，未重复添加':'链接已保存');if(result.items[0]?.stage==='saved')try{await box.action('extract',{id:result.items[0].id})}catch(e){error.value=app.errorMessage(e)}await refresh()}catch(e){error.value=app.errorMessage(e)}finally{working.value=''}}
async function act(action:string,id?:string){working.value=id||action;error.value='';try{const result=await box.action(action,id?{id}:{});if(result.reason)app.notify(linkErrors[result.reason]||result.reason);else if(action==='collect')app.notify(`采集完成：新增 ${result.count||0} 条${result.errors?.length?'，部分来源失败':''}`);await refresh()}catch(e){error.value=app.errorMessage(e)}finally{working.value=''}}
async function toggleDiscovery(){try{await box.action('set-discovery',{enabled:!box.discovery.value.enabled});await refresh()}catch(e){error.value=app.errorMessage(e)}}
onMounted(refresh)
</script>
<template><div class="page inbox-page"><div class="page-heading"><div><div class="eyebrow">YOUR SIGNAL INBOX</div><h1>先收下，再读懂<span class="orange">。</span></h1><p>一个链接，就是一条值得追踪的线索。</p></div><button class="icon-btn" aria-label="刷新收件箱" @click="refresh"><Icon name="RefreshCw"/></button></div><div class="inbox-tabs"><button v-for="t in ['收件箱','快讯']" :class="{active:tab===t}" @click="tab=t">{{t}}<span>{{box.items.value.filter(i=>t==='快讯'?i.origin==='collector':i.origin!=='collector').length}}</span></button></div><form v-if="tab==='收件箱'" class="form-card link-form" @submit.prevent="submit"><label>新闻、项目或模型的原文网址<input v-model="url" type="url" required maxlength="2000" placeholder="https://…" aria-label="资料网址"/></label><label>为什么值得关注（可选）<input v-model="reason" maxlength="1000" placeholder="例如：想了解这次编程能力升级"/></label><button class="btn primary" :disabled="!!working||!url.trim()"><Icon name="Plus" :size="16"/>{{working==='submit'?'正在收下…':'收下这个链接'}}</button><small class="muted">只提取已启用来源的网页元信息。资料不会直接发布；候选图片不自动转载。</small></form><section v-else class="form-card brief-status"><h3><Icon name="Rss" :size="18"/>官方原文快讯</h3><p>RSS、GitHub 和 Hugging Face 的原文标题与指标。未生成中文解读，未完成独立事实核验。</p><div class="inbox-actions"><button class="btn outline small" :disabled="!!working" @click="act('collect')">{{working==='collect'?'正在采集…':'立即采集'}}</button><button class="btn outline small" @click="toggleDiscovery">{{box.discovery.value.enabled?'暂停采集':'恢复采集'}}</button></div><small>{{box.discovery.value.enabled?(box.discovery.value.schedule==='hourly'?'后台每小时采集，无需打开网页':'采集已允许，定时器尚未配置'):'采集已暂停'}}<template v-if="last"> · 上次 {{dateLabel(last.started_at)}} · {{last.status==='running'?'处理中':last.status==='succeeded'?'完成':'部分失败'}} · 新增 {{last.count}} 条</template></small><p v-if="last?.errors?.length" class="form-hint">{{last.errors.map((e:any)=>linkErrors[e.code]||e.code||e).join('；')}}</p></section><p v-if="error" class="form-error" role="alert">{{error}}</p><div class="inbox-filter"><input v-model="query" aria-label="搜索资料" placeholder="搜索最近 200 条资料"/><select v-model="filter" aria-label="资料状态"><option>全部</option><option>待处理</option><option>已归档</option></select></div><article v-for="item in rows" :key="item.id" class="link-card"><div class="link-card-top"><span class="category-tag">{{item.category}}</span><small>{{stageLabels[item.stage]||item.stage}}</small></div><h2>{{item.title||'等待提取标题'}}</h2><a v-if="secureUrl(item.canonical_url)" :href="item.canonical_url" target="_blank" rel="noopener noreferrer" class="link-host">{{item.source_name||host(item.canonical_url)}}<Icon name="ExternalLink" :size="13"/></a><p v-if="item.excerpt" class="link-excerpt">{{item.excerpt}}</p><p v-if="item.reason" class="link-reason">收下的理由：{{item.reason}}</p><div v-if="item.tags.length" class="link-metrics"><span v-for="tag in item.tags" :key="tag"># {{tag}}</span></div><div v-if="item.metadata?.metrics" class="link-metrics"><span v-if="item.metadata.metrics.stars!=null">{{Number(item.metadata.metrics.stars).toLocaleString()}} 累计 stars</span><span v-if="item.metadata.metrics.downloads!=null">{{Number(item.metadata.metrics.downloads).toLocaleString()}} 平台窗口下载</span><span v-if="item.metadata.metrics.likes!=null">{{Number(item.metadata.metrics.likes).toLocaleString()}} 喜欢</span><span v-if="item.metadata.metrics.language">{{item.metadata.metrics.language}}</span></div><small class="muted">采集 {{dateLabel(item.observed_at)}}<template v-if="item.source_published_at"> · 原文 {{dateLabel(item.source_published_at)}}</template><template v-else> · 原文日期未确定，不能当作今日发布</template></small><p v-if="item.error_code" class="form-hint">{{linkErrors[item.error_code]||item.error_code}}</p><LinkAttachments v-if="item.origin==='agent'" :link-id="item.id"/><div class="inbox-actions"><button v-if="item.origin!=='collector'&&item.stage!=='archived'" class="btn outline small" :disabled="!!working" @click="act('extract',item.id)">{{working===item.id?'处理中…':'提取 / 重试'}}</button><RouterLink v-if="item.post_id" :to="`/edit/${item.post_id}`" class="btn outline small">查看文章</RouterLink><RouterLink v-else :to="{path:'/publish',query:{link:item.id}}" class="btn outline small">整理成手记<Icon name="Pencil" :size="13"/></RouterLink><button v-if="item.stage!=='archived'" class="icon-btn" aria-label="归档资料" :disabled="!!working" @click="act('archive',item.id)"><Icon name="CheckCheck" :size="18"/></button></div></article><div v-if="!rows.length" class="empty-state"><Icon name="Rss" :size="36"/><h2>{{tab==='快讯'?'等待第一批真实线索':'把值得关注的链接放在这里'}}</h2><p>{{tab==='快讯'?'启用来源后，后台会自动采集。没有资料时不会生成填充内容。':'从浏览器复制原文网址，粘贴到上方即可。'}}</p></div><RouterLink to="/admin" class="source-link">管理信息源与投稿凭证<Icon name="ArrowUpRight" :size="15"/></RouterLink></div></template>
